<?php

/**
 * Hand-written code. NOT generated by Speakeasy. Safe from regeneration.
 *
 * @see docs/REGENERATION.md
 */

declare(strict_types=1);

namespace Factuarea\Sdk\Custom\Request;

use Factuarea\Sdk\Utils\Options;

/**
 * Per-call options that stop the generated status-code retries (`429` and
 * `5xx`) for operations that must not be repeated blindly, such as submitting
 * to or cancelling at FACe: a `502` there can mean the administration did
 * receive the request (`transmission_uncertain`), so the caller reconciles
 * instead of resending.
 *
 * The generated retry loop still repeats a transport error (connection reset,
 * timeout) with the same `Idempotency-Key`, which the API answers by replaying
 * the first outcome. The `face-no-retry.yaml` overlay (and the final spec, which
 * no longer declares `x-speakeasy-retries` on those two operations) removes the
 * retry from the generated methods on the next regeneration; this helper covers
 * the current ones.
 *
 * ```php
 * $sdk->invoices->faceSubmissions->publicApiV1InvoicesFaceSubmissionsSubmit(
 *     company: $companyId, invoice: $id, idempotencyKey: $key, options: NoRetry::options(),
 * );
 * ```
 */
final class NoRetry
{
    public static function options(): Options
    {
        return Options::builder()->setRetryCodes([])->build();
    }
}
